simple.afterForm:
                [
    {
        "type": "divider"
    },
    {
        "type": "panel",
        "title": "取用授权（RBAC 收紧）",
        "body": {
            "type": "crud",
            "name": "credential-auth-list",
            "syncLocation": false,
            "footerToolbar": ["pagination", "statistics"],
            "api": {
                "url": "@query:NopCredentialAuth__findPage/items{roleId,createTime,createdBy},total",
                "data": {
                    "filter_credentialId": "${credentialId}",
                    "page": "${page}",
                    "pageSize": "${perPage}"
                }
            },
            "columns": [
                { "name": "roleId", "label": "角色ID" },
                { "name": "createTime", "label": "授权时间" },
                { "name": "createdBy", "label": "授权人" },
                {
                    "type": "operation",
                    "label": "操作",
                    "buttons": [
                        {
                            "type": "button",
                            "label": "撤销",
                            "level": "danger",
                            "actionType": "ajax",
                            "confirmText": "确认撤销该角色的取用授权？撤销后未命中授权角色用户的明文取用将被拒绝（无用户上下文的服务端调用不受影响）。",
                            "api": {
                                "url": "@mutation:NopCredentialAuth__revoke",
                                "data": {
                                    "credentialId": "${credentialId}",
                                    "roleId": "${roleId}"
                                }
                            }
                        }
                    ]
                }
            ]
        },
        "actions": [
            {
                "type": "button",
                "label": "授予角色",
                "level": "primary",
                "actionType": "dialog",
                "dialog": {
                    "title": "授予取用授权（幂等：已存在则不重复授予）",
                    "body": {
                        "type": "form",
                        "api": {
                            "url": "@mutation:NopCredentialAuth__grant",
                            "data": {
                                "credentialId": "${credentialId}",
                                "roleId": "${roleId}"
                            }
                        },
                        "body": [
                            {
                                "type": "select",
                                "name": "roleId",
                                "label": "角色",
                                "required": true,
                                "searchable": true,
                                "creatable": true,
                                "source": "@query:NopAuthRole__findList/value:roleId,label:roleName",
                                "desc": "共部署时可从角色列表选择；standalone 部署无角色服务时手工输入 roleId（可新建选项；后端仅校验非空，不做存在性校验）。"
                            }
                        ]
                    }
                }
            }
        ]
    },
    {
        "type": "panel",
        "title": "使用引用（收紧前核对）",
        "body": {
            "type": "crud",
            "name": "credential-usage-list",
            "syncLocation": false,
            "footerToolbar": ["pagination", "statistics"],
            "api": {
                "url": "@query:NopCredentialUsage__findPage/items{consumerRef,createTime},total",
                "data": {
                    "filter_credentialId": "${credentialId}",
                    "page": "${page}",
                    "pageSize": "${perPage}"
                }
            },
            "columns": [
                { "name": "consumerRef", "label": "消费者引用" },
                { "name": "createTime", "label": "登记时间" }
            ]
        }
    }
]
